namespace putgd {
RecentOperations::RecentOperations(OperationService& operations,QWidget* parent):QWidget(parent),operations_(operations){setObjectName("putgdWindow");VisualStyle::apply(*qApp);setWindowIcon(VisualStyle::icon("brand"));setWindowTitle("put.gd — Recent activity");resize(1000,700);auto* layout=new QVBoxLayout(this);layout->setContentsMargins(24,22,24,20);layout->setSpacing(14);
 layout->addWidget(VisualStyle::header("A little capture. A link to anywhere.","Follow each capture, upload and clipboard result. Retry only the step that needs attention.",this));
 count_=new QLabel("Recent operations",this);VisualStyle::role(count_,"sectionTitle");layout->addWidget(count_);
 empty_=new QLabel("Ready when you are.\nCapture a region, window, desktop or clipboard to see its progress here.",this);empty_->setWordWrap(true);empty_->setAlignment(Qt::AlignCenter);VisualStyle::role(empty_,"status");layout->addWidget(empty_);
 tree_=new QTreeWidget(this);tree_->setObjectName("recentOperations");tree_->setAccessibleName("Recent captures and individual outcomes");tree_->setHeaderLabels({"Capture / file","Operation ID / public URL","Upload","Clipboard / local copy","Details"});VisualStyle::decorateView(tree_,{2,3});tree_->setRootIsDecorated(true);tree_->setIndentation(22);tree_->setUniformRowHeights(true);tree_->header()->setStretchLastSection(false);for(int column=0;column<5;++column)tree_->header()->setSectionResizeMode(column,QHeaderView::Interactive);tree_->setColumnWidth(0,185);tree_->setColumnWidth(1,270);tree_->setColumnWidth(2,125);tree_->setColumnWidth(3,170);tree_->setColumnWidth(4,240);layout->addWidget(tree_,1);
 status_=new QLabel("Choose a capture to copy its result or retry a failed step.",this);status_->setAccessibleName("Activity status");status_->setWordWrap(true);VisualStyle::role(status_,"status");layout->addWidget(status_);auto* buttons=new QHBoxLayout;buttons->setSpacing(10);layout->addLayout(buttons);
 auto add=[this,buttons](const QString& label,const QString& name,auto fn){auto* button=new QPushButton(label,this);button->setObjectName(name);if(name=="copyOperationResult")VisualStyle::role(button,"primary");buttons->addWidget(button);connect(button,&QPushButton::clicked,this,[this,fn]{auto* row=tree_->currentItem();if(!row)return;while(row->parent())row=row->parent();const auto id=row->data(0,Qt::UserRole).toString();fn(id,[g=QPointer<RecentOperations>(this)](Error e,QJsonObject){if(g){VisualStyle::feedback(g->status_,e?e.code+": "+e.message:"Action accepted.",bool(e));g->refresh();}});});};
 add("Copy result only","copyOperationResult",[this](auto id,auto reply){operations_.copyResult(id,reply);});add("Retry operation","retryOperation",[this](auto id,auto reply){operations_.retry(id,reply);});add("Retry local save only","retryLocalSave",[this](auto id,auto reply){operations_.retryLocalSave(id,reply);});add("Cancel","cancelOperation",[this](auto id,auto reply){operations_.cancel(id,reply);});connect(&operations_,&OperationService::changed,this,[this]{refresh();});connect(&operations_,&OperationService::initialized,this,[this]{refresh();});if(operations_.ready())refresh();}
void RecentOperations::refresh(){const auto sequence=++request_;if(loadInFlight_){loadPending_=true;return;}loadInFlight_=true;operations_.recent([g=QPointer<RecentOperations>(this),sequence](Error e,QJsonObject data){if(!g)return;g->loadInFlight_=false;if(g->loadPending_){g->loadPending_=false;g->refresh();return;}if(sequence!=g->request_)return;if(e){VisualStyle::feedback(g->status_,e.code+": "+e.message,true);return;}QString selected;if(auto* row=g->tree_->currentItem()){while(row->parent())row=row->parent();selected=row->data(0,Qt::UserRole).toString();}g->tree_->clear();const auto values=data["operations"].toArray();g->empty_->setVisible(values.isEmpty());g->count_->setText(QString("Recent activity  ·  %1 captures").arg(values.size()));for(auto value:data["operations"].toArray()){auto op=value.toObject();auto* row=new QTreeWidgetItem(g->tree_,{op["action"].toString(),op["id"].toString(),op["state"].toString(),op["copyStatus"].toString(),op["error"].toObject()["message"].toString()});row->setData(0,Qt::UserRole,op["id"].toString());row->setIcon(0,VisualStyle::icon(op["action"].toString()));for(int column=0;column<5;++column)row->setToolTip(column,row->text(column));for(auto itemValue:op["items"].toArray()){auto item=itemValue.toObject();auto local=item["local"].toObject();auto* child=new QTreeWidgetItem(row,{item["artifact"].toObject()["name"].toString(),item["receipt"].toObject()["directUrl"].toString(),item["uploadStatus"].toString(),local["status"].toString()+" "+local["path"].toString(),item["error"].toObject()["message"].toString()+ (local["error"].toObject()["message"].toString().isEmpty()?QString{}:" Local save: "+local["error"].toObject()["message"].toString())+" Remote: "+item["remoteStatus"].toString()});child->setIcon(0,VisualStyle::icon(item["artifact"].toObject()["category"].toString()));for(int column=0;column<5;++column)child->setToolTip(column,child->text(column));}row->setExpanded(true);if(op["id"].toString()==selected)g->tree_->setCurrentItem(row);}});}
}
